(function(exports, undefined) {
"use strict";
tinymce.PluginManager.add("phpvnn", function(editor, url) {
    var editorSettings = editor.settings;

    editorSettings.file_browser_callback = function(id, value, type, win) {
        var btnBrowser = $('.browser-files-option');
        if(btnBrowser.length) {
            btnBrowser.eq(0).data('params','inputid='+id);
            btnBrowser.eq(0).trigger( 'click' );
        }
        // console.log('file_browser_callback',id, value, type,$(this),editorSettings);
    };
});

})(this);
